window.AUTH=window.AUTH||{};window.AUTH["23-1141"]={"d":"23-1141","id":"2024/23-1141","n":"Smith & Wesson Brands, Inc. v. Estados Unidos Mexicanos","briefs":[{"k":"petitioner","label":"Brief of petitioners Smith & Wesson Brands, Inc., et al.","date":"2024-11-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-1141/332815/20241126130359423_23-1141%20ts.pdf","side":"pet","n":45},{"k":"respondent","label":"Brief of respondent Estados Unidos Mexicanos","date":"2025-01-10","url":"https://www.supremecourt.gov/DocketPDF/23/23-1141/337036/20250110145559191_Mexico%20Response%20Brief%201-10-25%20Final.pdf","side":"res","n":77},{"k":"reply","label":"Reply of petitioners Smith & Wesson Brands, Inc., et al.","date":"2025-02-10","url":"https://www.supremecourt.gov/DocketPDF/23/23-1141/342331/20250210131117953_23-1141%20rb.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us1r38_j426.pdf","tr":true,"items":[{"t":"case","label":"Amazon Servs. LLC v. U.S. Dept. of Agric.","cite":"109 F.4th 573","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/109/573/","by":{"0":"35","2":"19"}},{"t":"case","label":"Anza v. Ideal Basic Steel Supply Corp.","cite":"547 U.S. 451","y":2006,"id":"2005/04-433","sc":1,"ar":1,"sum":"The ninth member - Justice Clarence Thomas - wrote that while he disagreed with the other justices' concern about directness, he too would have ruled in National's favor because the case had nothing to do with organized crime, RICO's original target.","sumSrc":"Oyez","by":{"0":"19, 23, 26","1":"36, 42, 43, 48","2":"2, 3, 4, 7, 13"}},{"t":"case","label":"Apple v. Pepper","cite":"587 U.S. 273","y":2019,"id":"2018/17-204","sc":1,"sum":"Respondents, who purchased apps for their iPhones though Apple’s App Store, were direct purchasers from Apple under Illinois Brick Co. v. Illinois, 431 U. S. 720, and may sue Apple for allegedly monopolizing the retail market for the sale of iPhone apps.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28","2":"3"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"op":2,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"49","2":"18"}},{"t":"case","label":"Assoc. Gen. Contractors of Cal., Inc. v. California State Council of Carpenters","cite":"459 U.S. 519","y":1983,"id":"1982/81-334","sc":1,"sum":"Based on the allegations of the complaint, the Union was not a person injured by reason of a violation of the antitrust laws within the meaning of § 4 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 23","1":"41, 48"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter of Cmtys. for a Great Or.","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"sum":"The Supreme Court held that habitat modification is a legitimate application of the word \"harm.\" First, the Court found that the Court of Appeals was incorrect in assuming that the words in the definition of \"take\" only apply to actions involving direct contact with endangered animals.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Bank of America Corp. v. City of Miami","cite":"581 U.S. 189","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"0":"18, 23, 28","1":"42, 44, 47, 48","2":"2, 3, 4, 12"}},{"t":"case","label":"Bridge v. Phoenix Bond & Indem. Co.","cite":"553 U.S. 639","y":2008,"id":"2007/07-210","sc":1,"ar":1,"sum":"The Court held in favor of Phoenix, stating that a plaintiff bringing a RICO claim based on mail fraud does not need to show that it actually relied on the defendant's misrepresentations. Plaintiffs do not lack standing merely because the false statements were made to a third party.","sumSrc":"Oyez","by":{"0":"19, 30","1":"8","2":"5"}},{"t":"case","label":"Camp v. Dema","cite":"948 F.2d 455","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/948/455/","by":{"0":"35","1":"26, 27","2":"16"}},{"t":"case","label":"City of Boston v. Smith & Wesson Corp.","cite":"2000 WL 1473568","y":2000,"court":"Mass. Super. Ct. July 13","ar":1,"by":{"0":"6","2":"7"}},{"t":"case","label":"City of Chicago v. Beretta, U.S.A., Corp.","cite":"821 N.E.2d 1099","y":2004,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/821/1099/","ar":2,"by":{"0":"25","1":"5, 6","2":"14"}},{"t":"case","label":"City of Philadelphia v. Beretta","cite":"126 F. Supp. 2d 882","y":2000,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/126/882/","by":{"0":"21"}},{"t":"case","label":"City of Philadelphia v. Beretta U.S.A. Corp.","cite":"277 F.3d 415","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/277/415/","sum":"Rejecting similar argument on motion to dismiss.","sumSrc":"brief:0","by":{"0":"24, 25, 27, 48","1":"50","2":"12"}},{"t":"case","label":"Consol. Rail Corp. v. Gottshall","cite":"512 U.S. 532","y":1994,"id":"1993/92-1956","sc":1,"sum":"The Court held that this test would best distinguish between genuine and fraudulent claims, and provide relief in the case of injury. The Court rejected the Third Circuit's holding that employers were liable for causing foreseeably stressful conditions, reasoning that this would extend to many types of everyday employment.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Direct Sales Co. v. United States","cite":"319 U.S. 703","y":1943,"id":"scdb/1942-132","sc":1,"op":10,"ar":14,"sum":"Noting the signifcance of “stimulation” and “active incitement to purchase”.","sumSrc":"opinion","by":{"0":"33, 36, 37","1":"13, 15, 21, 22, 24, 28, 32, 33","2":"20, 21"}},{"t":"case","label":"District of Columbia v. Beretta, U.S.A., Corp.","cite":"872 A.2d 633","y":2005,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/872/633/","op":1,"by":{"0":"25"}},{"t":"case","label":"Halberstam v. Welch","cite":"705 F.2d 472","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/705/472/","by":{"0":"34, 36, 38","1":"30, 31, 36"}},{"t":"case","label":"Hamilton v. Beretta U.S.A. Corp.","cite":"96 N.Y.2d 222","y":2001,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.Y.2d/96/222/","by":{"0":"48"}},{"t":"case","label":"Hemi Grp., LLC v. City of New York","cite":"559 U.S. 1","y":2010,"id":"2009/08-969","sc":1,"ar":9,"sum":"The Court held that the city of New York had standing to sue out-of-state cigarette vendors under the Racketeer Influenced and Corrupt Organizations Act.","sumSrc":"Oyez","by":{"0":"18, 19, 22–24, 27, 30","1":"42","2":"2, 3, 4, 5"}},{"t":"case","label":"Holmes v. Sec. Inv. Prot. Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"ar":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17–19, 26, 27","1":"41-43, 49","2":"2, 3, 5, 6, 7, 13"}},{"t":"case","label":"Kemper v. Deutsche Bank AG","cite":"911 F.3d 383","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/911/383/","by":{"0":"24"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"op":2,"ar":2,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"18–21, 26, 27, 30","1":"41-43, 47, 48, 50","2":"12, 13"}},{"t":"case","label":"Milwaukee & St. Paul Ry. Co. v. Kellogg","cite":"94 U.S. 469","y":1876,"id":"scdb/1876-197","sc":1,"ar":1,"sum":"Noting proximate cause “is ordinarily a question for the jury”.","sumSrc":"brief:1","by":{"0":"20","1":"34, 35, 39","2":"2, 5"}},{"t":"case","label":"Moon v. First Nat’l Bank of Benson","cite":"135 A. 114","y":1926,"court":"Pa.","url":"https://www.courtlistener.com/c/A./135/114/","by":{"0":"25"}},{"t":"case","label":"Nye & Nissen v. United States","cite":"336 U.S. 613","y":1949,"id":"scdb/1948-062","sc":1,"op":1,"sum":"Petitioners are a corporation and its president. An indictment charged them (and three employees of the corporation), in the first count, with conspiracy to defraud the United States from 1938 to 1945, in violation of § 37 of the Criminal Code (now 18 U. S. C. § 371); and, in six substantive counts, with filing false invoices with an agency of the United States, in violation of § 35 of the Criminal Code (now 18 U. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Pac. Ops. Offshore, LLP v. Valladolid","cite":"565 U.S. 207","y":2012,"id":"2011/10-507","sc":1,"sum":"The Court held that the Outer Continental Shelf Lands Act extends coverage for injuries that occurred as the result of operations conducted on the outer continental shelf to an employee, as long as the employee can establish a substantial connection between the injury and the employer’s extractive operations.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"op":3,"ar":7,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"0":"32, 33","1":"20, 30","2":"16"}},{"t":"case","label":"S. Pacific Co. v. Darnell-Taenzer Co.","cite":"245 U.S. 531","y":1918,"id":"scdb/1917-193","sc":1,"sum":"The fact that one who paid unreasonable freight charges has shifted, the burden by collecting from purchasers of the goods, does not prevent him from recovering the overpayments from the carrier, under an order of reparation made by the Interstate Commerce Commission. He is the proximate loser; his cause of action accrues immediately, without waiting for later events; the purchaser, lacking privity, cannot recover …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17","1":"17, 41, 47-50","2":"3"}},{"t":"case","label":"SEC v. Wash. Cnty. Util. Dist.","cite":"676 F.2d 218","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/218/","by":{"0":"35"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"0":"20","1":"28"}},{"t":"case","label":"Stahlecker v. Ford Motor Co.","cite":"667 N.W.2d 244","y":2003,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W.2d/667/244/","by":{"0":"25"}},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"op":12,"ar":22,"sum":"Plaintiffs’ allegations that the social-media-company defendants aided and abetted ISIS in its terrorist attack on a nightclub in Istanbul, Turkey fail to state a claim under 18 U. S. C. §2333(d)(2).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 12, 16, 32–37, 40, 41, 44–47, 49, 50","1":"3, 13, 15, 16, 19-21, 24, 26-31, 36","2":"15, 17, 18, 19, 20, 21, 22"}},{"t":"case","label":"United States v. Blankenship","cite":"970 F.2d 283","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/970/283/","sum":"Noting where “‘mere’ sale[s]” end and liability “begin[s]”.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"United States v. Peoni","cite":"100 F.2d 401","y":1938,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/100/401/","op":3,"by":{"0":"33"}},{"t":"case","label":"Waters v. Merchants’ Louisville Ins. Co.","cite":"11 Pet. 213","y":1837,"url":"https://www.courtlistener.com/c/Pet./11/213/","by":{"0":"18"}},{"t":"case","label":"Woodward v. Metro Bank of Dallas","cite":"522 F.2d 84","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/522/84/","by":{"0":"35","1":"26, 27","2":"16"}},{"t":"usc","label":"15 U.S.C. § 7901","url":"https://www.law.cornell.edu/uscode/text/15/7901","subs":["(a)(5)","(a)(7)","(b)(1)"],"stext":{"head":"§7901. Findings; purposes","paras":[[0,"(a) Findings"],[0,"Congress finds the following:"],[1,"(1) The Second Amendment to the United States Constitution provides that the right of the people to keep and bear arms shall not be infringed."],[1,"(2) The Second Amendment to the United States Constitution protects the rights of individuals, including those who are not members of a militia or engaged in military service or training, to keep and bear arms."],[1,"(3) Lawsuits have been commenced against manufacturers, distributors, dealers, and importers of firearms that operate as designed and intended, which seek money damages and other relief for the harm caused by the misuse of firearms by third parties, including criminals."],[1,"(4) The manufacture, importation, possession, sale, and use of firearms and ammunition in the United States are heavily regulated by Federal, State, and local laws. Such Federal laws include the Gun Control Act of 1968, the National Firearms Act [26 U.S.C. 5801 et seq.], and the Arms Export Control Act [22 U.S.C. 2751 et seq.]."],[1,"(5) Businesses in the United States that are engaged in interstate and foreign commerce through the lawful design, manufacture, marketing, distribution, importation, or sale to the public of firearms or ammunition products that have been shipped or transported in interstate or foreign commerce are not, and should not, be liable for the harm caused by those who criminally or unlawfully misuse firearm products or ammunition products that function as designed and intended."],[1,"(6) The possibility of imposing liability on an entire industry for harm that is solely caused by others is an abuse of the legal system, erodes public confidence in our Nation's laws, threatens the diminution of a basic constitutional right and civil liberty, invites the disassembly and destabilization of other industries and economic sectors lawfully competing in the free enterprise system of the United States, and constitutes an unreasonable burden on interstate and foreign commerce of the United States."],[1,"(7) The liability actions commenced or contemplated by the Federal Government, States, municipalities, and private interest groups and others are based on theories without foundation in hundreds of years of the common law and jurisprudence of the United States and do not represent a bona fide expansion of the common law. The possible sustaining of these actions by a maverick judicial officer or petit jury would expand civil liability in a manner never contemplated by the framers of the Constitution, by Congress, or by the legislatures of the several States. Such an expansion of liability would constitute a deprivation of the rights, privileges, and immunities guaranteed to a citizen of the United States under the Fourteenth Amendment to the United States Constitution."],[1,"(8) The liability actions commenced or contemplated by the Federal Government, States, municipalities, private interest groups and others attempt to use the judicial branch to circumvent the Legislative branch of government to regulate interstate and foreign commerce through judgments and judicial decrees thereby threatening the Separation of Powers doctrine and weakening and undermining important principles of federalism, State sovereignty and comity between the sister States."],[0,"(b) Purposes"],[0,"The purposes of this chapter are as follows:"],[1,"(1) To prohibit causes of action against manufacturers, distributors, dealers, and importers of firearms or ammunition products, and their trade associations, for the harm solely caused by the criminal or unlawful misuse of firearm products or ammunition products by others when the product functioned as designed and intended."],[1,"(2) To preserve a citizen's access to a supply of firearms and ammunition for all lawful purposes, including hunting, self-defense, collecting, and competitive or recreational shooting."],[1,"(3) To guarantee a citizen's rights, privileges, and immunities, as applied to the States, under the Fourteenth Amendment to the United States Constitution, pursuant to section 5 of that Amendment."],[1,"(4) To prevent the use of such lawsuits to impose unreasonable burdens on interstate and foreign commerce."],[1,"(5) To protect the right, under the First Amendment to the Constitution, of manufacturers, distributors, dealers, and importers of firearms or ammunition products, and trade associations, to speak freely, to assemble peaceably, and to petition the Government for a redress of their grievances."],[1,"(6) To preserve and protect the Separation of Powers doctrine and important principles of federalism, State sovereignty and comity between sister States."],[1,"(7) To exercise congressional power under article IV, section 1 (the Full Faith and Credit Clause) of the United States Constitution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7901?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7901. Findings; purposes","tname":"Commerce and Trade","by":{"0":"5, 7, 20, 21, 27, 38, 39","1":"1, 29, 6, 4, 37","2":"6, 7"}},{"t":"usc","label":"15 U.S.C. § 7902","url":"https://www.law.cornell.edu/uscode/text/15/7902","stext":{"head":"§7902. Prohibition on bringing of qualified civil liability actions in Federal or State court","paras":[[0,"(a) In general"],[0,"A qualified civil liability action may not be brought in any Federal or State court."],[0,"(b) Dismissal of pending actions"],[0,"A qualified civil liability action that is pending on October 26, 2005, shall be immediately dismissed by the court in which the action was brought or is currently pending."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7902?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7902. Prohibition on bringing of qualified civil liability actions in Federal or State court","tname":"Commerce and Trade","by":{"0":"5, 7, 21","1":"4, 49"}},{"t":"usc","label":"15 U.S.C. § 7903","url":"https://www.law.cornell.edu/uscode/text/15/7903","subs":["(5)(A)","(5)(A)(i)","(5)(A)(ii)","(5)(A)(iii)","(5)(A)(iii)(I)","(5)(A)(iii)(II)","(5)(A)(iv)","(5)(A)(v)","(5)(C)"],"stext":{"head":"§7903. Definitions","paras":[[0,"In this chapter:"],[0,"(1) Engaged in the business"],[1,"The term \"engaged in the business\" has the meaning given that term in section 921(a)(21) of title 18, and, as applied to a seller of ammunition, means a person who devotes time, attention, and labor to the sale of ammunition as a regular course of trade or business with the principal objective of livelihood and profit through the sale or distribution of ammunition."],[0,"(2) Manufacturer"],[1,"The term \"manufacturer\" means, with respect to a qualified product, a person who is engaged in the business of manufacturing the product in interstate or foreign commerce and who is licensed to engage in business as such a manufacturer under chapter 44 of title 18."],[0,"(3) Person"],[1,"The term \"person\" means any individual, corporation, company, association, firm, partnership, society, joint stock company, or any other entity, including any governmental entity."],[0,"(4) Qualified product"],[1,"The term \"qualified product\" means a firearm (as defined in subparagraph (A) or (B) of section 921(a)(3) of title 18), including any antique firearm (as defined in section 921(a)(16) of such title), or ammunition (as defined in section 921(a)(17)(A) of such title), or a component part of a firearm or ammunition, that has been shipped or transported in interstate or foreign commerce."],[0,"(5) Qualified civil liability action"],[0,"(A) In general"],[2,"The term \"qualified civil liability action\" means a civil action or proceeding or an administrative proceeding brought by any person against a manufacturer or seller of a qualified product, or a trade association, for damages, punitive damages, injunctive or declaratory relief, abatement, restitution, fines, or penalties, or other relief, resulting from the criminal or unlawful misuse of a qualified product by the person or a third party, but shall not include—"],[3,"(i) an action brought against a transferor convicted under section 924(h) of title 18, or a comparable or identical State felony law, by a party directly harmed by the conduct of which the transferee is so convicted;"],[3,"(ii) an action brought against a seller for negligent entrustment or negligence per se;"],[3,"(iii) an action in which a manufacturer or seller of a qualified product knowingly violated a State or Federal statute applicable to the sale or marketing of the product, and the violation was a proximate cause of the harm for which relief is sought, including—"],[4,"(I) any case in which the manufacturer or seller knowingly made any false entry in, or failed to make appropriate entry in, any record required to be kept under Federal or State law with respect to the qualified product, or aided, abetted, or conspired with any person in making any false or fictitious oral or written statement with respect to any fact material to the lawfulness of the sale or other disposition of a qualified product; or"],[4,"(II) any case in which the manufacturer or seller aided, abetted, or conspired with any other person to sell or otherwise dispose of a qualified product, knowing, or having reasonable cause to believe, that the actual buyer of the qualified product was prohibited from possessing or receiving a firearm or ammunition under subsection (g) or (n) of section 922 of title 18;"],[3,"(iv) an action for breach of contract or warranty in connection with the purchase of the product;"],[3,"(v) an action for death, physical injuries or property damage resulting directly from a defect in design or manufacture of the product, when used as intended or in a reasonably foreseeable manner, except that where the discharge of the product was caused by a volitional act that constituted a criminal offense, then such act shall be considered the sole proximate cause of any resulting death, personal injuries or property damage; or"],[3,"(vi) an action or proceeding commenced by the Attorney General to enforce the provisions of chapter 44 of title 18 or chapter 53 of title 26."],[0,"(B) Negligent entrustment"],[2,"As used in subparagraph (A)(ii), the term \"negligent entrustment\" means the supplying of a qualified product by a seller for use by another person when the seller knows, or reasonably should know, the person to whom the product is supplied is likely to, and does, use the product in a manner involving unreasonable risk of physical injury to the person or others."],[0,"(C) Rule of construction"],[2,"The exceptions enumerated under clauses (i) through (v) of subparagraph (A) shall be construed so as not to be in conflict, and no provision of this chapter shall be construed to create a public or private cause of action or remedy."],[0,"(D) Minor child exception"],[2,"Nothing in this chapter shall be construed to limit the right of a person under 17 years of age to recover damages authorized under Federal or State law in a civil action that meets 1 of the requirements under clauses (i) through (v) of subparagraph (A)."],[0,"(6) Seller"],[1,"The term \"seller\" means, with respect to a qualified product—"],[2,"(A) an importer (as defined in section 921(a)(9) of title 18) who is engaged in the business as such an importer in interstate or foreign commerce and who is licensed to engage in business as such an importer under chapter 44 of title 18;"],[2,"(B) a dealer (as defined in section 921(a)(11) of title 18) who is engaged in the business as such a dealer in interstate or foreign commerce and who is licensed to engage in business as such a dealer under chapter 44 of title 18; or"],[2,"(C) a person engaged in the business of selling ammunition (as defined in section 921(a)(17)(A) of title 18) in interstate or foreign commerce at the wholesale or retail level."],[0,"(7) State"],[1,"The term \"State\" includes each of the several States of the United States, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, and the Commonwealth of the Northern Mariana Islands, and any other territory or possession of the United States, and any political subdivision of any such place."],[0,"(8) Trade association"],[1,"The term \"trade association\" means—"],[2,"(A) any corporation, unincorporated association, federation, business league, professional or business organization not organized or operated for profit and no part of the net earnings of which inures to the benefit of any private shareholder or individual;"],[2,"(B) that is an organization described in section 501(c)(6) of title 26 and exempt from tax under section 501(a) of such title; and"],[2,"(C) 2 or more members of which are manufacturers or sellers of a qualified product."],[0,"(9) Unlawful misuse"],[1,"The term \"unlawful misuse\" means conduct that violates a statute, ordinance, or regulation as it relates to the use of a qualified product."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7903?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7903. Definitions","tname":"Commerce and Trade","by":{"0":"2, 5, 17, 20, 29, 31, 39","1":"49, 4, 45, 29, 4, 1, 5, 14, 16, 18, 22, 29, 37, 39, 46, 47, 50, 5, 18, 22, 29, 32, 38, 18, 22, 29, 4, 5, 6, 17, 38, 47, 48","2":"11, 12, 14"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","stext":{"head":"§2. Principals","paras":[[0,"(a) Whoever commits an offense against the United States or aids, abets, counsels, commands, induces or procures its commission, is punishable as a principal."],[0,"(b) Whoever willfully causes an act to be done which if directly performed by him or another would be an offense against the United States, is punishable as a principal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":3,"head":"§2. Principals","tname":"Crimes and Criminal Procedure","by":{"0":"33"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(a)(6)","(m)","(t)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"31","1":"9, 9, 39, 9, 39"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(1)(A)","(a)(3)(A)","(h)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"39","1":"39, 39, 29"}},{"t":"usc","label":"18 U.S.C. § 1923","url":"https://www.law.cornell.edu/uscode/text/18/1923","by":{"0":"47"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","by":{"0":"12"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"op":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Aetna Cas. & Sur. Co. v. Leahey Constr. Co.","cite":"219 F.3d 519","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/519/","by":{"1":"27"}},{"t":"case","label":"Babb v. Wilkie","cite":"589 U.S. 399","y":2020,"id":"2019/18-882","sc":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Brown v. Commonwealth","cite":"685 S.E.2d 43","y":2009,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/685/43/","by":{"1":"51"}},{"t":"case","label":"Century Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"op":1,"ar":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"1":"19, 20"}},{"t":"case","label":"City of Miami v. Wells Fargo & Co.","cite":"140 S. Ct. 1259","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/1259/","sc":1,"by":{"1":"44"}},{"t":"case","label":"City of Miami v. Wells Fargo & Co.","cite":"923 F.3d 1260","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/923/1260/","by":{"1":"44"}},{"t":"case","label":"Cottrell v. Am. Fam. Mut. Ins. Co., S.I.","cite":"930 F.3d 969","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/969/","by":{"1":"42"}},{"t":"case","label":"County of Los Angeles v. Mendez","cite":"581 U.S. 420","y":2017,"id":"2016/16-369","sc":1,"sum":"The Court determined that the U.S. Court of Appeals for the Ninth Circuit’s provocation rule has no basis in the Fourth Amendment, and that the lower court erroneously conflated multiple Fourth Amendment violation claims.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"CSX Transp., Inc. v. McBride","cite":"564 U.S. 685","y":2011,"id":"2010/10-235","sc":1,"sum":"The Supreme Court affirmed the lower court order in an opinion by Justice Ruth Bader Ginsburg. \"The charge proper in FELA cases, we hold, simply tracks the language Congress employed, informing juries that a defendant railroad caused or contributed to a plaintiff employee's injury if the railroad's negligence played any part in bringing about the injury,\" Ginsburg wrote for the majority.","sumSrc":"Oyez","by":{"1":"34, 45","2":"4"}},{"t":"case","label":"Dew v. Crown Derrick Erectors, Inc.","cite":"208 S.W.3d 448","y":2006,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/208/448/","by":{"1":"51"}},{"t":"case","label":"Exxon Co., U.S.A. v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Hall v. Beals","cite":"396 U.S. 45","y":1969,"id":"1969/39","sc":1,"sum":"Appellants, who moved to Colorado in June 1968, were refused permission to vote in the November 1968 presidential election because they could not meet Colorado's six-month statutory residency requirement. They brought this class action challenging the constitutionality of that restriction and seeking, inter alia, mandamus and injunctive relief. The District Court upheld the statute and dismissed the complaint. After …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Kent v. Commonwealth","cite":"771 N.E.2d 770","y":2002,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/771/770/","by":{"1":"34, 35"}},{"t":"case","label":"Kligler v. Att’y Gen.","cite":"198 N.E.3d 1229","y":2022,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.3d/198/1229/","by":{"1":"48"}},{"t":"case","label":"Lillie v. Thompson","cite":"332 U.S. 459","y":1947,"id":"scdb/1947-008","sc":1,"sum":"A complaint under the Federal Employers' Liability Act alleged that the hours, location and circumstances of the complainant's work created a likelihood that she would suffer injuries through the criminal acts of a person not an employee; that the railroad failed to exercise its duty of taking reasonable measures to protect her against the foreseeable danger, and that she suffered injuries as a result of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36","2":"9"}},{"t":"case","label":"Metge v. Baehler","cite":"762 F.2d 621","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/762/621/","by":{"1":"26","2":"16"}},{"t":"case","label":"Minnesota v. Fleet Farm LLC","cite":"679 F. Supp. 3d 825","y":2023,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/679/825/","op":1,"by":{"1":"7"}},{"t":"case","label":"Monsen v. Consolidated Dressed Beef Co., Inc.","cite":"579 F.2d 793","y":1978,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/579/793/","by":{"1":"27","2":"16"}},{"t":"case","label":"National Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"1":"39"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"op":2,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"1":"34, 51"}},{"t":"case","label":"Smith & Wesson Corp. v. City of Gary","cite":"875 N.E.2d 422","y":2007,"court":"Ind. Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/875/422/","by":{"1":"7"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"United States v. Page","cite":"2024 WL 5154496","y":2024,"court":"7th Cir. Dec. 18","by":{"1":"33"}},{"t":"case","label":"U.S. Bank Nat’l Ass’n ex rel. CWCapital Asset Mgmt. LLC v. Village at Lakeridge, LLC","cite":"583 U.S. 387","y":2018,"id":"2017/15-1509","sc":1,"sum":"The Court held that a designation of non-statutory insider status is reviewable under the standard of clear error because the \"mixed question\" of law and fact at issue is primarily factual.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Vining v. Avis Rent-A-Car Systems, Inc.","cite":"354 So. 2d 54","y":1977,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/354/54/","by":{"1":"36","2":"8"}},{"t":"case","label":"Page(s) Williams v. Beemiller, Inc.","cite":"100 A.D.3d 143","y":2012,"court":"N.Y. App. Div., 4th Dept.","url":"https://www.courtlistener.com/c/A.D.3d/100/143/","by":{"1":"7"}},{"t":"usc","label":"9 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/9/16","by":{"1":"6"}},{"t":"usc","label":"18 U.S.C. § 923","url":"https://www.law.cornell.edu/uscode/text/18/923","subs":["(a)","(g)"],"by":{"1":"39, 39"}},{"t":"usc","label":"28 U.S.C. § 2283","url":"https://www.law.cornell.edu/uscode/text/28/2283","by":{"1":"6"}},{"t":"usc","label":"42 U.S.C. § 2210","url":"https://www.law.cornell.edu/uscode/text/42/2210","subs":["(b)(1)"],"by":{"1":"6"}},{"t":"usc","label":"49 U.S.C. § 40101","url":"https://www.law.cornell.edu/uscode/text/49/40101","by":{"1":"6"}},{"t":"reg","label":"15 C.F.R. § 738.4","url":"https://www.ecfr.gov/current/title-15/section-738.4","by":{"1":"39"}},{"t":"case","label":"City of Oakland v. Wells Fargo & Co.","cite":"14 F.4th 1030","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/14/1030/","by":{"2":"12"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"General Motors, LLC v. FCA US, LLC","cite":"44 F.4th 548","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/44/548/","by":{"2":"4"}},{"t":"case","label":"Laborers Local 17 Health and Benefit Fund v. Philip Morris, Inc.","cite":"191 F.3d 229","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/191/229/","by":{"2":"3, 4"}},{"t":"case","label":"SEIU v. Philip Morris Inc.","cite":"249 F.3d 1068","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/249/1068/","by":{"2":"6"}},{"t":"case","label":"Stewart v. Dutra Constr. Co.","cite":"543 U.S. 481","y":2005,"id":"2004/03-814","sc":1,"sum":"The Court held that the Revised Statutes of 1873 specified that in any act passed after 1871, \"vessel\" included any watercraft capable of transportation. The requirement that a worker be on a vessel \"in navigation,\" required by the LHWCA, simply meant that the vessel be capable of transportation.","sumSrc":"Oyez","by":{"2":"7"}}]};